+  assert.strictEqual(Buffer.stringLength(new Uint8Array(ab)), expected);
+  assert.strictEqual(Buffer.stringLength(new Uint16Array(ab.slice(0, 16))),
+                     Buffer.from(ab.slice(0, 16)).toString().length);
